663	  async function assertExplicitResumeIntentAllowed(
664	    req: Request,
665	    res: Response,
666	    issue: { id: string; companyId: string; status: string; assigneeAgentId: string | null },
667	  ) {
668	    if (issue.status === "cancelled") {
669	      res.status(409).json({
670	        error: "Cancelled issues must be restored through the dedicated restore flow",
671	        details: {
672	          issueId: issue.id,
673	          status: issue.status,
674	        },
675	      });
676	      return false;
677	    }
678	
679	    if (!isExplicitResumeCapableStatus(issue.status)) {
680	      res.status(409).json({
681	        error: "Issue is not resumable through comment follow-up intent",
682	        details: { issueId: issue.id, status: issue.status },
683	      });
684	      return false;
685	    }
686	
687	    const activePauseHold = await treeControlSvc.getActivePauseHoldGate(issue.companyId, issue.id);
688	    if (activePauseHold) {
689	      res.status(409).json({
690	        error: "Issue follow-up blocked by active subtree pause hold",
691	        details: {
692	          issueId: issue.id,
693	          holdId: activePauseHold.holdId,
694	          rootIssueId: activePauseHold.rootIssueId,
695	          mode: activePauseHold.mode,
696	        },
697	      });
698	      return false;
699	    }
700	
701	    if (issue.status === "blocked") {
702	      const readiness = await svc.getDependencyReadiness(issue.id);
703	      if (readiness.unresolvedBlockerCount > 0) {
704	        res.status(409).json({
705	          error: "Issue follow-up blocked by unresolved blockers",
706	          details: {
707	            issueId: issue.id,
708	            unresolvedBlockerIssueIds: readiness.unresolvedBlockerIssueIds,
709	          },
710	        });
711	        return false;
712	      }
713	    }
714	
715	    if (req.actor.type !== "agent") return true;
716	
717	    const actorAgentId = req.actor.agentId;
718	    if (!actorAgentId) {
719	      res.status(403).json({ error: "Agent authentication required" });
720	      return false;
721	    }
722	    if (!issue.assigneeAgentId) {
723	      res.status(409).json({
724	        error: "Issue follow-up requires an assigned agent",
725	        details: { issueId: issue.id, actorAgentId },
726	      });
727	      return false;
728	    }
729	    if (issue.assigneeAgentId === actorAgentId) return true;
730	    if (await hasActiveCheckoutManagementOverride(actorAgentId, issue.companyId, issue.assigneeAgentId)) {
731	      return true;
732	    }
733	
734	    res.status(403).json({
735	      error: "Agent cannot request follow-up for another agent's issue",
736	      details: {
737	        issueId: issue.id,
738	        assigneeAgentId: issue.assigneeAgentId,
739	        actorAgentId,
740	      },
741	    });
742	    return false;
743	  }
